@page "/dashboard"
@using sv_3dab93d6076e469dbdc031c9153d5eb4.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted mb-4">@WarehouseState.CurrentWarehouseName</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4">
                    <AlertBadge />
                </p>
                <p class="text-muted small">
                    Polling every 10 seconds
                    @if (_isPolling)
                    {
                        <span class="text-success ms-2">● Active</span>
                    }
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="lead">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Last Updated</h5>
                <p class="lead">@_lastUpdated.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private bool _isPolling;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        AlertService.StartPolling();
        _isPolling = true;
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertChanged()
    {
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
        _isPolling = false;
    }
}

